        int 端口 = 门.getLocalPort();
        Thread 守门的 = new Thread(() -> {
            try {
                Socket 客 = 门.accept();
                PrintWriter 写 = 写手(客);
                BufferedReader 读 = 读者(客);
                写.println("收到：" + 读.readLine());
                写.println("收到：" + 读.readLine());
            } catch (IOException e) {
            }
        });
        守门的.start();

        Socket 自己 = new Socket("127.0.0.1", 端口);
